package com.hau.question.application.service;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import com.hau.question.application.port.out.*; import com.hau.question.domain.model.*; import com.hau.question.infrastructure.rabbitmq.AiGenerationPayload; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class AiQuestionImportServiceTest {@Test void duplicateEventDoesNotDuplicateQuestions(){var q=mock(QuestionRepository.class);var events=mock(ProcessedEventRepository.class);UUID id=UUID.randomUUID();when(events.exists(id)).thenReturn(false,true);when(q.save(any())).thenAnswer(i->i.getArgument(0));var service=new AiQuestionImportService(q,events,Clock.systemUTC());var payload=new AiGenerationPayload("job",UUID.randomUUID(),"CNTT",UUID.randomUUID(),UUID.randomUUID(),null,List.of(new AiGenerationPayload.AiQuestion("1","Q",null,null,QuestionType.SINGLE_CHOICE,Difficulty.EASY,List.of(new AiGenerationPayload.AiOption("A","a",null,null,true,0),new AiGenerationPayload.AiOption("B","b",null,null,false,1)))));assertEquals(1,service.importCompleted(id,payload));assertEquals(0,service.importCompleted(id,payload));verify(q,times(1)).save(any());}}
